'use strict';
const SODIUM_WHO=2000,SODIUM_DV=2300;
let verifiedFoodsOnly=false;
function nutrientValue(value,portion=1){return typeof value==='number'&&Number.isFinite(value)?Math.round(value*portion*10)/10:null;}
function nutrientText(value,unit=''){return value===null||!Number.isFinite(value)?'Not available':value.toLocaleString(undefined,{maximumFractionDigits:1})+(unit?' '+unit:'');}
function nutritionDailyValue(key){const values=state.meals.map(m=>typeof m[key]==='number'&&Number.isFinite(m[key])?m[key]:null);if(!values.length)return '0';if(values.every(x=>x===null))return 'Unknown';return (values.some(x=>x===null)?'≥ ':'')+nutrientText(values.reduce((a,v)=>a+(v||0),0));}
function foodImage(f,large=false){return f.photo?`<img class="${large?'dish-hero':'dish-thumb'}" src="${esc(f.photo)}" alt="Example of ${esc(f.name)}" loading="lazy" decoding="async">`:`<span class="food-art">${f.emoji||'🍲'}</span>`;}
function nutritionSource(f){return f.nutritionVerified?'DOST-FNRI reference · '+(f.variant||'specific food record'):'Nutrition not verified · recipe varies';}
function foodNutritionFacts(f,amount=1){return ['kcal','protein','sodium','sugar'].map((k,i)=>`<div><b>${nutrientText(nutrientValue(f[k],amount))}</b><small>${['kcal','g protein','mg sodium','g total sugar'][i]}</small></div>`).join('');}
function sodiumGuidance(items,{includeDay=true}={}){
 const valid=items.filter(x=>x&&Number.isFinite(x.portion)&&x.portion>0),missing=valid.filter(x=>nutrientValue(x.food.sodium,x.portion)===null),known=valid.filter(x=>nutrientValue(x.food.sodium,x.portion)!==null),sodium=Math.round(known.reduce((s,x)=>s+x.food.sodium*x.portion,0)),warnings=[];
 if(!valid.length)return '';
 if(missing.length)warnings.push({title:'Sodium data is incomplete',text:`${missing.map(x=>x.food.name).join(', ')} has no verified sodium value here. A photo cannot measure hidden salt, sauces or seasonings. Check a package label or recipe; missing is not zero.`});
 if(known.length&&sodium>=460)warnings.push({title:'Higher-sodium serving',text:`This selection contains ${missing.length?'at least ':''}${sodium.toLocaleString()} mg sodium, about ${Math.round(sodium/SODIUM_DV*100)}% of the FDA adult label daily value (2,300 mg). 20% DV or more per serving is high.`});
 if(known.length&&sodium*3>=SODIUM_WHO)warnings.push({title:'Think about three meals',text:`This same portion three times would provide ${missing.length?'at least ':''}${(sodium*3).toLocaleString()} mg sodium before other foods or condiments. That reaches or exceeds the WHO adult recommendation of less than 2,000 mg/day. Try less sauce or seasoning, a smaller portion, and different foods across meals.`});
 if(includeDay&&known.length){const day=state.meals.reduce((s,m)=>s+(typeof m.sodium==='number'&&Number.isFinite(m.sodium)?m.sodium:0),0);if(day+sodium>=SODIUM_WHO)warnings.push({title:'Check your day’s total',text:`Your logged sodium plus this selection is about ${(day+sodium).toLocaleString()} mg${state.meals.some(m=>typeof m.sodium!=='number')?' or more; some logged foods have missing data':''}. The WHO figure is a general adult guide; an individual target can differ.`});}
 if(!warnings.length)warnings.push({title:'Keep the whole plate in mind',text:'This portion does not trigger the high-sodium label benchmark. Sauces and recipes vary. Add variety across meals with vegetables, fruit, staple foods and protein; eating the same dish three times is not automatically unsafe.'});
 return `<section class="nutrition-cautions" aria-label="Food considerations">${warnings.map(w=>`<div class="nutrition-caution"><strong>${esc(w.title)}</strong><p>${esc(w.text)}</p></div>`).join('')}<p class="nutrition-context">General adult guidance. Children and people with clinician-prescribed restrictions may need different advice. Total sugar is not the same as added/free sugar.</p><a href="https://www.who.int/news-room/fact-sheets/detail/salt-reduction" target="_blank" rel="noopener">WHO sodium guidance</a> · <a href="https://www.fda.gov/food/nutrition-education-resources-materials/sodium-your-diet" target="_blank" rel="noopener">FDA label guide</a></section>`;
}
function nutritionFoodList(){return foods.filter(f=>(!verifiedFoodsOnly||f.nutritionVerified)&&(filter==='All'||f.cat===filter)&&(f.name+' '+(f.aliases||[]).join(' ')+' '+(f.variant||'')).toLowerCase().includes(query.toLowerCase())).map(f=>`<button class="food-row" data-food="${f.id}">${foodImage(f)}<span class="food-info"><strong>${esc(f.name)}</strong><small>${esc(f.serving)}<br>${f.kcal===null?'Nutrition not verified':nutrientText(f.kcal,'kcal')+' · '+nutrientText(f.protein,'g protein')}</small><span class="food-data-badge ${f.nutritionVerified?'verified':''}">${f.nutritionVerified?'FNRI reference':'Recipe-dependent'}</span></span><span class="food-plus">+</span></button>`).join('')||'<div class="empty">No matching dishes.<br>Try another name or turn off the reference-only filter.</div>';}
function nutritionFoodScreen(){return `<section class="screen">${header()}${title('Food you know, checked with care')}<p class="subtle">A Filipino food guide with source details and portion-based nutrition checks.</p>${photoCheckerBanner()}<label class="searchbox">${ic('search')}<input id="food-search" type="search" placeholder="Search adobo, tinola, pancit…" aria-label="Search Filipino food" value="${esc(query)}"></label><div class="filters">${['All','Ulam','Sides','Snacks','Drinks'].map(f=>`<button class="chip ${filter===f?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="food-library-options"><button class="chip ${verifiedFoodsOnly?'selected':''}" data-action="verified-foods" aria-pressed="${verifiedFoodsOnly}">FNRI records only</button><button class="text-btn" data-action="food-sources">Sources & photo credits</button></div><p class="field-help">${foods.length} foods · ${foods.filter(f=>f.nutritionVerified).length} matched reference records. Photos show examples, not a measured recipe. Missing nutrients are not counted as zero.</p><div id="food-list">${nutritionFoodList()}</div><div class="section-top"><h2>Logged today</h2><span class="subtle">${state.meals.length} entries</span></div>${state.meals.map(m=>`<div class="meal-log"><div class="event-emoji">${m.emoji||'🍽️'}</div><span>${esc(m.name)}<small>${esc(m.meal)} · ${typeof m.kcal==='number'?nutrientText(m.kcal,'kcal'):'Energy not available'} · ${m.portion} serving${m.portion===1?'':'s'}</small></span><button class="delete-btn" data-delete-meal="${m.uid}" aria-label="Remove ${esc(m.name)}">${ic('trash')}</button></div>`).join('')||'<div class="empty">Your food log is ready for the first meal.</div>'}<p class="tiny-note">Reference composition describes a specific food and preparation. Your actual recipe, serving and added sauces can differ. Older demo log entries retain their original estimates.</p></section>`;}
function nutritionFoodModal(){const f=selectedFood;if(!f)return;activeModal='food';showModal(f.name,`${foodImage(f,true)}<p class="subtle food-variant">${esc(f.variant||'Recipe varies')}<br>${esc(f.serving)} · ${nutrientText(f.servingGrams*portion,'g')} selected</p><div class="portion-control"><div>Servings<small>Adjust to your actual portion</small></div><div class="stepper"><button data-portion="-0.5" aria-label="Decrease serving">−</button><output>${portion}</output><button data-portion="0.5" aria-label="Increase serving">+</button></div></div><div class="scan-nutrients">${foodNutritionFacts(f,portion)}</div>${sodiumGuidance([{food:f,portion}])}<label class="field"><span>Meal</span><select id="meal-type"><option>Lunch</option><option>Breakfast</option><option>Dinner</option><option>Snack</option></select></label><div class="food-provenance"><strong>${esc(nutritionSource(f))}</strong><p>${esc(f.prepNote||'Confirm that the dish and preparation match this entry.')}</p>${f.sourceUrl?`<a href="${esc(f.sourceUrl)}" target="_blank" rel="noopener">Open nutrient source</a>`:''}${f.photoCredit?`<p class="photo-credit">Example photo: ${esc(f.photoCredit.author)} · <a href="${esc(f.photoCredit.source)}" target="_blank" rel="noopener">${esc(f.photoCredit.license)}</a></p>`:''}</div><div class="save-bar"><button class="primary" data-action="save-food">${ic('plus')}Add to my food log</button></div>`);}
function makeFoodLog(f,amount,meal,uid,source='catalog'){return {uid,loggedAt:new Date().toISOString(),name:f.name,emoji:f.emoji||'🍲',foodId:f.id,portion:amount,servingGrams:f.servingGrams,meal,source,nutritionSource:f.sourceUrl||'Unverified recipe entry',nutritionVerified:!!f.nutritionVerified,...Object.fromEntries(['kcal','sodium','sugar','protein'].map(k=>[k,nutrientValue(f[k],amount)]))};}
function nutritionSaveFood(){const f=selectedFood;if(!f)return;setVibeMoment('meal');state.meals.push(makeFoodLog(f,portion,$('#meal-type').value,'meal-'+Date.now()));save();render(true);showModal('Meal logged',`<div class="success-card"><div class="success-emoji">🌱</div><h3>Your food log is updated.</h3><p>${esc(f.name)} · ${portion} serving${portion===1?'':'s'}</p></div>${sodiumGuidance([{food:f,portion}],{includeDay:false})}<button class="primary" data-action="done-food">Back to food log</button>`);}
function nutritionSourcesModal(){showModal('Sources & photo credits',`<div class="food-provenance"><h3>Nutrition</h3><p>The FNRI badge means the numbers come from a specific public DOST-FNRI PhilFCT report, scaled from 100 g to the stated portion. The source link is shown on each record. A homemade dish must not inherit a canned food’s values.</p><a href="https://i.fnri.dost.gov.ph/fct/library" target="_blank" rel="noopener">DOST-FNRI PhilFCT library</a><p>Foods without an exact verified match stay in the guide with missing nutrient fields. No value is inferred from the photo. Existing prototype estimates are not a clinical record.</p><h3>Food photographs</h3><p>Example photographs come from Wikimedia Commons. Individual authors, source files and reusable licenses are listed below and on each food record. Photos were resized and converted to WebP.</p>${foods.filter(f=>f.photoCredit).map(f=>`<p><strong>${esc(f.name)}</strong><br>${esc(f.photoCredit.author)} · <a href="${esc(f.photoCredit.source)}" target="_blank" rel="noopener">${esc(f.photoCredit.license)}</a></p>`).join('')}</div><button class="primary" data-action="close">Done</button>`);}
function nutritionDayNote(){const missing=state.meals.filter(m=>['kcal','sodium','sugar','protein'].some(k=>typeof m[k]!=='number')).length,knownSodium=state.meals.reduce((a,m)=>a+(typeof m.sodium==='number'?m.sodium:0),0);return `<div class="daily-data-note">${missing?`${missing} logged item${missing===1?' has':'s have'} missing nutrients. Totals include available values only and may understate intake.`:'Nutrition totals reflect the selected records and portions; actual recipes vary.'}${knownSodium>=SODIUM_WHO?`<strong>Your logged sodium is ${knownSodium.toLocaleString()} mg${missing?' or more':''}. This reaches the general WHO adult daily recommendation of less than 2,000 mg. Consider a less salty next meal; follow any personal clinician guidance.</strong>`:''}</div>`;}
function installNutrition(){foodList=nutritionFoodList;food=nutritionFoodScreen;foodModal=nutritionFoodModal;saveFood=nutritionSaveFood;actions['save-food']=nutritionSaveFood;actions['food-sources']=nutritionSourcesModal;actions['verified-foods']=()=>{verifiedFoodsOnly=!verifiedFoodsOnly;render(true);};const baseToday=today;today=()=>baseToday().replace('<div class="quick-actions">',nutritionDayNote()+'<div class="quick-actions">');}
